// Some portions generated by Codex
package org.eclipse.rdf4j.repository.sparql.query;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.FOAF;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParser;
import org.junit.jupiter.api.Test;

class QueryStringUtilBindingTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void inlinesUnprojectedTripleObjectWithoutChangingFormatting() {
		String query = "SELECT ?instance WHERE { ?instance a ?type }";
		assertEquals("SELECT ?instance WHERE { ?instance a <http://xmlns.com/foaf/0.1/Person> }",
				QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON)));
	}

	@Test
	void doesNotReplaceVariableSpellingInsideOtherTokens() {
		String query = "SELECT ?instance ?label ?iri WHERE {\n"
				+ "?instance a $type . BIND(\"?type $type\" AS ?label) "
				+ "BIND(<urn:test?type> AS ?iri) # ?type $type\n}";
		String expected = "SELECT ?instance ?label ?iri WHERE {\n"
				+ "?instance a <http://xmlns.com/foaf/0.1/Person> . BIND(\"?type $type\" AS ?label) "
				+ "BIND(<urn:test?type> AS ?iri) # ?type $type\n}";
		assertEquals(expected, QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON)));
	}

	@Test
	void retainsProjectedVariableAndBoundExpression() {
		for (String query : new String[] {
				"SELECT ?instance ?type WHERE { ?instance a ?type }",
				"SELECT * WHERE { ?instance a ?type }",
				"SELECT ?instance WHERE { ?instance a ?type FILTER(BOUND(?type)) }" }) {
			String result = QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON));
			assertTrue(result.contains("VALUES"), result);
			assertTrue(result.contains("?instance a ?type"), result);
			new SPARQLParser().parseQuery(result, null);
		}
	}

	@Test
	void combinesSafeInlineBindingAndRequiredMapping() {
		String query = "SELECT ?instance ?name WHERE { ?instance a ?type; <urn:name> ?name }";
		MapBindingSet bindings = binding("type", FOAF.PERSON);
		bindings.addBinding("name", VF.createLiteral("Alice"));
		String result = QueryStringUtil.getTupleQueryString(query, bindings);
		assertTrue(result.contains("?instance a <http://xmlns.com/foaf/0.1/Person>"), result);
		assertTrue(result.contains("VALUES (?name )"), result);
		assertFalse(result.contains("?type"), result);
		new SPARQLParser().parseQuery(result, null);
	}

	@Test
	void rejectsLocalValuesOwnershipRatherThanFilteringItsRows() {
		String query = "SELECT ?type WHERE { VALUES ?type { <urn:one> <urn:two> } }";
		assertThrows(UnsupportedOperationException.class,
				() -> QueryStringUtil.getTupleQueryString(query, binding("type", VF.createIRI("urn:one"))));
	}

	@Test
	void doesNotBypassNestedScopeRejectionByInliningItsTerms() {
		for (String query : new String[] {
				"SELECT ?instance WHERE { { SELECT ?instance WHERE { ?instance a ?type } } }",
				"SELECT ?instance WHERE { SERVICE <urn:endpoint> { ?instance a ?type } }" }) {
			assertThrows(UnsupportedOperationException.class,
					() -> QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON)));
		}
	}

	@Test
	void askUsesTheSameSafeSubstitution() {
		assertEquals("ASK { ?instance a <http://xmlns.com/foaf/0.1/Person> }",
				QueryStringUtil.getBooleanQueryString("ASK { ?instance a ?type }", binding("type", FOAF.PERSON)));
	}

	@Test
	void constructRetainsVariableUsedByItsTemplate() {
		String query = "CONSTRUCT { ?instance a ?type } WHERE { ?instance a ?type }";
		String result = QueryStringUtil.getGraphQueryString(query, binding("type", FOAF.PERSON));
		assertTrue(result.startsWith("CONSTRUCT { ?instance a ?type }"), result);
		assertTrue(result.contains("VALUES"), result);
		new SPARQLParser().parseQuery(result, null);
	}

	@Test
	void preservesRawOffsetsAfterEscapedUnicodeAndWindowsLineEndings() {
		String query = "SELECT ?instance ?text WHERE {\r\n\tBIND(\"\\U0001F600\\u000A?type\" AS ?text)\r\n"
				+ "\t?instance a ?type . # ?type\r\n}";
		String result = QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON));
		assertEquals(query.replace("?instance a ?type", "?instance a <http://xmlns.com/foaf/0.1/Person>"), result);
		new SPARQLParser().parseQuery(result, null);
	}

	@Test
	void matchesWholeUnicodeVariableNamesAndDoesNotRescanInsertedValues() {
		String query = "SELECT ?instance WHERE { ?instance <urn:p> ?x; <urn:q> $xé; <urn:r> ?xy }";
		MapBindingSet bindings = binding("x", VF.createLiteral("?xé ?xy"));
		bindings.addBinding("xé", FOAF.PERSON);
		String result = QueryStringUtil.getTupleQueryString(query, bindings);
		assertTrue(result.contains("\"?xé ?xy\""), result);
		assertTrue(result.contains("<urn:q> <http://xmlns.com/foaf/0.1/Person>"), result);
		assertTrue(result.endsWith("<urn:r> ?xy }"), result);
		new SPARQLParser().parseQuery(result, null);
	}

	@Test
	void escapesInsertedIriDelimitersAsOneTerm() {
		String result = QueryStringUtil.getTupleQueryString("SELECT ?instance WHERE { ?instance <urn:p> ?value }",
				binding("value", VF.createIRI("urn:value> . ?malicious <urn:p> <urn:o> #")));
		new SPARQLParser().parseQuery(result, null);
		assertFalse(result.contains("<urn:value> . ?malicious"), result);
	}

	@Test
	void rejectsMalformedLanguageTagsInBothInlineAndValuesBindings() {
		Value injected = VF.createLiteral("label", "en . ?s ?p ?o } #");
		assertThrows(IllegalArgumentException.class,
				() -> QueryStringUtil.getTupleQueryString("SELECT ?s WHERE { ?s <urn:p> ?value }",
						binding("value", injected)));
		assertThrows(IllegalArgumentException.class,
				() -> QueryStringUtil.getTupleQueryString("SELECT ?value WHERE { ?s <urn:p> ?value }",
						binding("value", injected)));
	}

	@Test
	void preservesUniformExistingValuesAndRejectsUnverifiedBlankNodes() {
		String query = "SELECT ?type WHERE { VALUES ?type { <http://xmlns.com/foaf/0.1/Person> } }";
		new SPARQLParser().parseQuery(QueryStringUtil.getTupleQueryString(query, binding("type", FOAF.PERSON)), null);
		assertThrows(QueryEvaluationException.class,
				() -> QueryStringUtil.getTupleQueryString("SELECT ?instance WHERE { ?instance <urn:p> ?value }",
						binding("value", VF.createBNode("unverified"))));
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}
}
